 case=work/label;tests=case/'tests-soft-port';shutil.copytree(work/'tests-original',tests);cmd=[str(case/'lua'),'-e','_soft=true;_port=true','all.lua'];p=subprocess.run(cmd,cwd=tests,capture_output=True,text=True,timeout=300,preexec_fn=limits);(case/'upstream-soft-port.stdout').write_text(p.stdout);(case/'upstream-soft-port.stderr').write_text(p.stderr);results[label]={'exit':p.returncode,'completed':'final OK !!!' in p.stdout,'command':cmd,'stdout_sha256':hashlib.sha256(p.stdout.encode()).hexdigest(),'stderr_sha256':hashlib.sha256(p.stderr.encode()).hexdigest()};assert p.returncode==0 and results[label]['completed'],(label,p.stderr);print(label,'passed',flush=True)
